"ក៏មានហាងភីហ្សាថ្មីមួយក្បែរសាកលវិទ្យាល័យដែរ ដែលជាកន្លែងពេញនិយមបំផុតសម្រាប់និស្សិតនៅពេលល្ងាច។"
