"focus": "Stance & hedging (arguably · to a large extent · it could be argued that) · Absolute constructions (His authority unchallenged, …)",
"write": "សរសេរ ២៥០ ពាក្យ វាយតម្លៃសម័យសង្គមរាស្ត្រនិយម ទាំងសមិទ្ធផល និងចំណុចខ្វះខាត ដោយប្រើ arguably, to a large extent, it could be argued that និង absolute constructions។",
