(function () {
  const R = XC.reading || [];
  Object.keys(XC.readingHistory).forEach(lv => {
    const slots = R.map((r, i) => r.lv === lv ? i : -1).filter(i => i >= 0);
    XC.readingHistory[lv].forEach((ch, k) => { const c = Object.assign({ lv, long: true, hist: true }, ch); if (k < slots.length) R[slots[k]] = c; else R.push(c); });
    if (XC.readingHistoryComplete && XC.readingHistoryComplete[lv]) slots.slice(XC.readingHistory[lv].length).reverse().forEach(i => R.splice(i, 1));
  });
  (XC.readingExtra || []).forEach(x => R.push(x));
})();
